from mpmath import pi, sqrt, hankel1, hankel2, mpf, matrix

def transformationMatrix(f, k_z, m, epsilon_n, mu_n, rho):
    return matrix([[-2*1j*pi*epsilon_n*f*((mpf(1)/mpf(2))*hankel1(m - 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)) - mpf(1)/mpf(2)*hankel1(m + 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)))/sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2), -2*1j*pi*epsilon_n*f*((mpf(1)/mpf(2))*hankel2(m - 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)) - mpf(1)/mpf(2)*hankel2(m + 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)))/sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2), -k_z*m*hankel1(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))/(rho*(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), -k_z*m*hankel2(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))/(rho*(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))], [0, 0, hankel1(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), hankel2(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))], [-k_z*m*hankel1(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))/(rho*(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), -k_z*m*hankel2(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2))/(rho*(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), 2*1j*pi*f*mu_n*((mpf(1)/mpf(2))*hankel1(m - 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)) - mpf(1)/mpf(2)*hankel1(m + 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)))/sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2), 2*1j*pi*f*mu_n*((mpf(1)/mpf(2))*hankel2(m - 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)) - mpf(1)/mpf(2)*hankel2(m + 1, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)))/sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)], [hankel1(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), hankel2(m, rho*sqrt(4*pi**2*epsilon_n*f**2*mu_n - k_z**2)), 0, 0]])
